 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** The supported language the client prefers by its Accept-Language header, else `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  const value = Array.isArray(header) ? header.join(",") : header;
+  if (typeof value !== "string") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of value.split(",")) {
+    const [range, ...attrs] = part.trim().split(";");
+    const lang = range.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const attr of attrs) {
+      const [k, v] = attr.split("=").map((x) => x.trim());
+      if (k.toLowerCase() === "q") q = /^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(v ?? "") ? Number(v) : 0;
+    }
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
